<script setup lang="ts">
import {reactive,ref,watch} from 'vue'
import {useI18n} from 'vue-i18n'
import {storeToday} from '../time'
import {validMoney} from '../payrollUi'
import type {Payment,PaymentMethod} from '../payrollTypes'
const props=defineProps<{remaining:string|null;employeeId:string;settlementMonth?:string;payments:Payment[];locked:boolean}>(),emit=defineEmits<{save:[id:string,body:Record<string,unknown>]}>(),{locale}=useI18n(),x=(z:string,e:string)=>locale.value.startsWith('en')?e:z
const reverse=ref(''),error=ref(''),draft=reactive({amount:'',paymentDate:storeToday(),method:'cash' as PaymentMethod,bank:'',reference:'',note:''})
const minimumDate=()=>{const p=available().find(p=>p.id===reverse.value);return p?.paymentDate||((props.settlementMonth||'')?props.settlementMonth+'-01':'')}
const available=()=>props.payments.filter(p=>!p.reversesId&&!props.payments.some(r=>r.reversesId===p.id))
watch(reverse,id=>{const p=available().find(p=>p.id===id);draft.amount=p?.amount||'';draft.method=p?.method||'cash';draft.bank=p?.bank||''})
function save(){if(props.locked)return;const original=available().find(p=>p.id===reverse.value);if(!validMoney(draft.amount)||Number(draft.amount)<=0||(!original&&(props.remaining===null||Number(draft.amount)>Number(props.remaining)))||!draft.paymentDate||draft.paymentDate>storeToday()||draft.paymentDate<minimumDate()||!draft.note.trim()||(draft.method==='bank'&&(!draft.bank.trim()||!draft.reference.trim()))){error.value=x('请核对正额、现金余额、付款日期和付款凭证。','Review positive amount, cash balance, payment date and evidence.');return}error.value='';emit('save',crypto.randomUUID(),{employeeId:props.employeeId,amount:original?.amount||draft.amount,paymentDate:draft.paymentDate,method:original?.method||draft.method,bank:(original?.method||draft.method)==='cash'?'':(original?.bank||draft.bank).trim(),reference:draft.reference.trim(),note:draft.note.trim(),reversesId:original?.id||null})}
</script>
<template><form class="wf-section" @submit.prevent="save"><h3>{{x('补发现金付款登记／冲正','Supplemental cash payment / reversal')}}</h3><p>{{x('登记实际已发生付款；不会发起银行支付。未知或负余额不能登记新付款。','Record payments already made; no bank transfer is initiated. Unknown or negative balances cannot create new payments.')}}</p><fieldset :disabled="locked"><label>{{x('付款或整笔冲正','Payment or full reversal')}}<select v-model="reverse" :aria-label="x('付款或整笔冲正','Payment or full reversal')"><option value="">{{x('新增付款登记','Register payment')}}</option><option v-for="p in available()" :key="p.id" :value="p.id">{{x('整笔冲正','Full reversal')}} {{p.paymentDate}} · {{p.amount}} · {{p.reference}}</option></select></label><div class="wf-grid"><label>{{x('现金付款金额','Cash payment amount')}}<input v-model="draft.amount" inputmode="decimal" required :disabled="!!reverse" :aria-label="x('现金付款金额','Cash payment amount')"></label><label>{{x('实际付款日期','Actual payment date')}}<input v-model="draft.paymentDate" type="date" required :max="storeToday()" :min="minimumDate()" :aria-label="x('实际付款日期','Actual payment date')"></label><label>{{x('付款方式','Payment method')}}<select v-model="draft.method" :disabled="!!reverse" :aria-label="x('付款方式','Payment method')"><option value="cash">{{x('现金','Cash')}}</option><option value="bank">{{x('银行','Bank')}}</option><option value="paynow">PayNow</option><option value="other">{{x('其他','Other')}}</option></select></label><label v-if="draft.method!=='cash'">{{x('银行／付款资料','Bank / payment details')}}<input v-model="draft.bank" maxlength="100" :disabled="!!reverse"></label></div><label>{{x('付款回执','Payment reference')}}<input v-model="draft.reference" maxlength="100" :aria-label="x('付款回执','Payment reference')"></label><label>{{x('付款说明','Payment note')}}<textarea v-model="draft.note" maxlength="500" required :aria-label="x('付款说明','Payment note')"/></label><button type="submit" :disabled="locked||(!reverse&&(remaining===null||Number(remaining)<=0))">{{x('保存付款登记','Save payment record')}}</button></fieldset><p v-if="error" role="alert">{{error}}</p></form></template>
